      this.spark(SPARK.STAR, this.v[7], rnd(0.6, -0.6), rnd(o.rise ?? 1.4, 0.2), rnd(0.6, -0.6), rnd(o.life ?? 0.7, 0.35), o.size ?? 0.22, 0.02, col, 1, (options.spin=rnd(4,-4),options));
