      Math.abs(next[0]) < 1000 && Math.abs(next[1]) < 1000 && Math.abs(next[2]) < 1000 &&
      ((previous[0] < center[0] - broadRadius && next[0] < center[0] - broadRadius) ||
       (previous[0] > center[0] + broadRadius && next[0] > center[0] + broadRadius) ||
       (previous[2] < center[2] - broadRadius && next[2] < center[2] - broadRadius) ||
